   function makeItems(){
     const data=[]; Object.entries(categories).forEach(([type,c])=>c.books.slice(0,3).forEach((title,i)=>data.push({kind:'book',type,title,color:c.color}))); // 12 books
     trashIcons.forEach(icon=>data.push({kind:'trash',icon})); dustIcons.forEach(icon=>data.push({kind:'dust',icon}));
     // Duplicate total is 21: 12 books + 5 litter + 4 dust.
-    return data.map((item,i)=>({...item,id:`item-${i}`,pos:positions[(i*7)%positions.length],rot:`${[-13,9,-7,14,4][i%5]}deg`}));
+    return data.map((item,i)=>({...item,id:`item-${i}`,pos:positions[(i*10)%positions.length],rot:`${[-13,9,-7,14,4][i%5]}deg`}));
   }
   function say(message){const el=document.getElementById('status');el.textContent=message;el.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>el.classList.remove('show'),1350)}
   function chime(ok){if(!sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.value=ok?660:210;g.gain.setValueAtTime(.055,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.start();o.stop(ctx.currentTime+.21)}catch(e){}}
   function draw(){clutter.innerHTML='';items.filter(x=>!x.done).forEach(item=>{const el=document.createElement('button');el.className=`item ${item.kind}${selected===item.id?' selected':''}`;el.dataset.id=item.id;el.style.left=`${item.pos[0]}%`;el.style.top=`${item.pos[1]}%`;el.style.setProperty('--rot',item.rot);el.setAttribute('aria-label',item.kind==='book'?`${item.title}, ${item.type}`:`${item.kind==='trash'?'Litter':'Dust'}: ${item.icon}`);if(item.kind==='book'){el.textContent=item.title;el.style.background=`linear-gradient(90deg,${item.color},${item.color}dd)`}else{el.textContent=item.icon}el.addEventListener('click',()=>pick(item.id));clutter.appendChild(el)});document.querySelectorAll('.shelf-target').forEach(el=>el.classList.toggle('active',selected&&items.find(x=>x.id===selected)?.kind==='book'));document.getElementById('binTarget').classList.toggle('active',selected&&items.find(x=>x.id===selected)?.kind==='trash');document.getElementById('dustTarget').classList.toggle('active',selected&&items.find(x=>x.id===selected)?.kind==='dust')}
